const paths={Home:'m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',Search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',Compose:'M16 3l5 5-12 12-6 1 1-6Z M14 5l5 5',Notifications:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',Messages:'M21 11a9 9 0 0 1-9 9H3l2-5A9 9 0 1 1 21 11Z',Publishing:'M4 5h16v16H4Z M8 2v6 M16 2v6 M4 11h16',Settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',Image:'M3 3h18v18H3Z M3 16l5-5 5 5 4-4 4 4 M16 7h.01',Smile:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M8 14q4 5 8 0 M8 8h.01 M16 8h.01',Link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',Heart:'M12 21 3 12C-3 4 6-2 12 5 18-2 27 4 21 12Z',Reply:'M9 10H3l6-6 M3 10h10q8 0 8 10',Repost:'M4 8h14l-4-4 M20 16H6l4 4 M18 8v5 M6 16v-5',Bookmark:'M6 3h12v19l-6-5-6 5Z',More:'M5 12h.01 M12 12h.01 M19 12h.01',Sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',Plus:'M12 5v14 M5 12h14',Arrow:'M5 12h14 M14 7l5 5-5 5',Globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3q8 9 0 18-8-9 0-18'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.Globe}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let page='Home',filter='All networks',state='normal',modal='',drafts=JSON.parse(localStorage.getItem('zing-design-drafts')||'[]'),messages=[],search='';
const posts=[{id:1,name:'Sofia Chen',handle:'sofia.design',network:'Bluesky',time:'12m',initials:'SC',color:'green',body:'The best ideas happen when different worlds meet. Been thinking a lot about the spaces between design, nature, and the internet lately. 🌱',art:true,likes:128,replies:16,reposts:24},{id:2,name:'Marcus Wright',handle:'marcus@mastodon.social',network:'Mastodon',time:'38m',initials:'MW',color:'purple',body:'A smaller, more intentional internet. That’s what I’m here for.\n\nWhat’s one corner of the web that still feels like a neighborhood to you?',likes:86,replies:32,reposts:11},{id:3,name:'Amara Okafor',handle:'amara.studio',network:'Threads',time:'1h',initials:'AO',color:'blue',body:'Make something because you want it to exist. Share it because someone else might need it. ✨',likes:204,replies:18,reposts:0}];
function post(p){return `<article class="card post"><div class="post-head"><button class="avatar ${p.color}" data-profile="${p.id}" aria-label="View ${p.name}">${p.initials}</button><div><div class="post-name"><button class="name" data-profile="${p.id}">${p.name}</button><span class="network ${p.network.toLowerCase()}">${p.network}</span></div><div class="handle">@${p.handle} · ${p.time}</div></div><button class="more" data-menu="${p.id}" aria-label="More actions">${icon('More')}</button></div><p class="post-body">${esc(p.body).replace(/\n/g,'<br>')}</p>${p.art?'<div class="artwork" role="img" aria-label="Editorial artwork: Stay curious. Keep growing."><span class="art-label">A LITTLE REMINDER</span><span class="art-text">Stay curious.<br>Keep growing.</span></div>':''}<div class="post-actions"><button data-reply="${p.id}">${icon('Messages')} ${p.replies}</button><button data-repost="${p.id}" aria-label="Repost">${icon('Repost')} ${p.reposts||''}</button><button data-like="${p.id}" class="${p.liked?'liked':''}" aria-label="Like">${icon('Heart')} ${p.likes}</button><button data-save="${p.id}" aria-label="Bookmark">${icon('Bookmark')}</button><button data-share="${p.id}" aria-label="Copy link">${icon('Link')}</button></div></article>`}
function composer(full=false){return `<section class="card composer"><div class="composer-row"><div class="avatar">AG</div><textarea id="compose-text" aria-label="Post text" placeholder="What’s on your mind, Agim?" ${full?'style="min-height:150px"':''}></textarea></div>${full?'<div class="field"><span>Publish to</span><div class="row"><label><input type="checkbox" name="destination" value="Bluesky" checked> Bluesky</label><label><input type="checkbox" name="destination" value="Mastodon" checked> Mastodon</label><label><input type="checkbox" name="destination" value="Threads"> Threads</label></div></div><label class="field">Schedule (your local time)<input type="datetime-local" id="schedule"></label>':''}<div id="attachment" class="small"></div><div class="composer-footer"><div class="tools"><button data-upload aria-label="Attach image">${icon('Image')}</button><button data-emoji aria-label="Add emoji">${icon('Smile')}</button><button data-go="Compose" aria-label="Schedule post">${icon('Publishing')}</button><span class="small">${full?'':'<span style="color:var(--accent)">●</span> 2 accounts'}</span></div><div>${full?'<button class="secondary" data-draft>Save draft</button> ':''}<button class="primary" data-publish>Post ${icon('Arrow')}</button></div></div><input hidden type="file" id="image-file" accept="image/*"></section>`}
function main(){if(page==='Home')return `${composer()}<div class="tabs">${['All networks','Bluesky','Mastodon','Threads'].map(t=>`<button class="${t===filter?'active':''}" data-filter="${t}">${t==='All networks'?'For you':t}</button>`).join('')}<button class="filter" data-toast="You’re seeing the latest sample posts" aria-label="Feed options">${icon('Settings')}</button></div>${feed()}`;
if(page==='Compose')return `<h1 class="title">A little spark.</h1><p class="subtitle">One thought. All your worlds.</p><div class="notice">Design preview · publishing is simulated. No connected account is contacted.</div>${composer(true)}`;
if(page==='Search')return `<h1 class="title">Find your people.</h1><p class="subtitle">Good conversations start with a little curiosity.</p><form id="search-form" class="searchbox">${icon('Search')}<input name="q" value="${esc(search)}" placeholder="Search people, posts, and topics" aria-label="Search"><button class="primary">Search</button></form><div class="tabs"><button class="active">Top results</button><button data-toast="Sample people are included below">People</button><button data-toast="Sample posts are included below">Posts</button></div>${posts.filter(p=>(p.body+p.name+p.handle).toLowerCase().includes(search.toLowerCase())).map(post).join('')||'<div class="card empty"><h2>No results yet</h2>Try “design”, “internet”, or “Sofia”.</div>'}`;
if(page==='Notifications')return `<h1 class="title">A little connection.</h1><p class="subtitle">The conversations you’re part of.</p><div class="card">${[['SC','green','Sofia Chen liked your post.','Bluesky · 8m'],['MW','purple','Marcus Wright replied: “This is exactly why I love the open web.”','Mastodon · 23m'],['AO','blue','Amara Okafor followed you.','Threads · 1h']].map(([i,c,t,n])=>`<button class="notification full" data-profile="1"><span class="avatar ${c}">${i}</span><span style="text-align:left">${t}<br><span class="meta">${n}</span></span></button>`).join('')}</div>`;
if(page==='Messages')return `<h1 class="title">Closer conversations.</h1><p class="subtitle">A shared inbox. Every conversation stays on its own network.</p><div class="notice">Sample Bluesky conversation. Private messages are never cross-posted.</div><div class="card chat"><div class="chat-list"><button><span class="avatar green">SC</span><span><strong>Sofia Chen</strong><br><small>Bluesky · Just now</small></span></button><button data-toast="Sample Mastodon conversation"><span class="avatar purple">MW</span><span>Marcus Wright<br><small>Mastodon · 2h</small></span></button></div><div class="conversation"><div class="row"><strong>Sofia Chen</strong><span class="network">Bluesky</span></div><p class="meta">TODAY · SAMPLE CONVERSATION</p><div class="bubble">Hey! Have you seen the new community garden project? Thought you’d love it 🌿</div><div class="bubble mine">I have! Such a thoughtful use of the space.</div>${messages.map(m=>`<div class="bubble mine">${esc(m)}</div>`).join('')}<form id="message-form" class="message-form"><input name="message" aria-label="Message" placeholder="Write a message…" required><button class="primary" aria-label="Send message">${icon('Arrow')}</button></form></div></div>`;
if(page==='Publishing')return `<h1 class="title">Ideas, in motion.</h1><p class="subtitle">Your drafts, scheduled posts, and a clear view of every delivery.</p><div class="tabs"><button class="active">Drafts <span class="pill">${drafts.length}</span></button><button data-toast="No scheduled sample posts">Scheduled</button><button data-deliveries>Delivery history</button></div>${drafts.length?drafts.map((d,i)=>`<div class="card form-card"><div class="row"><span class="pill">${d.schedule?'Scheduled':'Draft'}</span><button data-delete-draft="${i}" class="meta">Delete</button></div><p class="post-body">${esc(d.text)}</p><button class="secondary" data-edit-draft="${i}">Continue writing ${icon('Arrow')}</button></div>`).join(''):'<div class="card empty">'+icon('Publishing')+'<h2>Room for your next idea.</h2><p>Save a thought for later, or schedule a little spark.</p><button class="primary" data-go="Compose">Create a post</button></div>'}`;
if(page==='Settings')return `<h1 class="title">Make yourself at home.</h1><p class="subtitle">Your accounts, your preferences, your corner of the internet.</p><div class="card form-card"><div class="section-heading"><h2>Connected accounts</h2><span class="pill">Sample data</span></div>${['Bluesky','Mastodon','Threads'].map(n=>`<div class="connection"><span class="network-logo ${n.toLowerCase()}">${n==='Threads'?'@':n==='Mastodon'?'m':'🦋'}</span><div><div class="name">${n}</div><div class="meta">${n==='Threads'?'App approval required':'@agim'+(n==='Mastodon'?'@mastodon.social':'.bsky.social')}</div></div><button class="secondary" style="margin-left:auto" data-connect="${n}">${n==='Threads'?'Set up':'Manage'}</button></div>`).join('')}<button class="secondary full" data-connect="Mastodon">+ Connect another account</button></div><div class="card form-card"><h2 style="font-size:16px">Appearance</h2><label class="field">Theme<select id="theme-select">${['system','light','dark'].map(t=>`<option ${t===(localStorage.getItem('zing-theme')||'system')?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="card form-card"><h2 style="font-size:16px">Account & security</h2><div class="stack"><button class="secondary" data-auth="login">Preview sign-in and registration</button><button class="secondary" data-toast="Sample sessions · Current browser">Active sessions</button><button class="secondary" data-delete-account>Delete account</button></div></div>`;
return ''}
function feed(){if(state==='loading')return '<div class="card empty" role="status">Gathering your worlds…</div>';if(state==='empty')return '<div class="card empty"><h2>Your world starts here.</h2><p>Connect an account and follow a few people to fill your feed.</p><button class="primary" data-go="Settings">Connect accounts</button></div>';if(state==='disconnected')return '<div class="notice">Your Mastodon connection has expired. <button data-connect="Mastodon"><u>Reconnect</u></button></div>';if(state==='rate-limit')return '<div class="notice warning">Bluesky is taking a breather. Updates resume in 60 seconds; your other networks are still available.</div>'+posts.filter(p=>p.network!=='Bluesky').map(post).join('');return posts.filter(p=>filter==='All networks'||p.network===filter).map(post).join('')}
function sidebar(){return `<aside class="sidebar"><a class="brand" href="#Home"><img src="assets/zing-icon.svg" alt="Zing mark">Zing<span style="color:var(--blue)">.</span></a><nav class="nav" aria-label="Main navigation">${['Home','Search','Notifications','Messages','Publishing','Settings'].map(n=>`<button data-page="${n}" data-go="${n}" class="${page===n?'active':''}">${icon(n)}<span>${n}</span>${n==='Notifications'?'<span class="badge">3</span>':''}</button>`).join('')}</nav><button class="primary" data-go="Compose">${icon('Compose')} Create a post</button><div class="sidebar-bottom"><div class="prototype">DESIGN PREVIEW · SAMPLE DATA</div><button class="account full" data-profile="0"><span class="avatar">AG</span><span style="text-align:left"><span class="name">Agim</span><br><span class="handle">Your connected world</span></span>${icon('More')}</button></div></aside>`}
function right(){return `<aside class="rightbar"><form class="searchbox" id="side-search">${icon('Search')}<input name="q" placeholder="Search the connected world" aria-label="Search the connected world"><span class="pill">⌘ K</span></form><section class="card right-card"><div class="section-heading"><h2>Your worlds</h2><a href="#Settings">Manage</a></div>${['Bluesky','Mastodon','Threads'].map(n=>`<div class="connection"><span class="network-logo ${n.toLowerCase()}">${n==='Threads'?'@':n==='Mastodon'?'m':'🦋'}</span><div><div class="name small">${n}</div><div class="meta">${n==='Threads'?'Setup needed':'@agim'+(n==='Bluesky'?'.bsky.social':'@mastodon.social')}</div></div><span class="${n==='Threads'?'pill':'dot'}">${n==='Threads'?'!':''}</span></div>`).join('')}<button class="secondary full small" data-go="Settings">${icon('Plus')} Connect an account</button></section><section class="card right-card"><div class="section-heading"><h2>In the conversation</h2>${icon('Globe')}</div>${[['Design & creativity','#BuildInPublic','2.4k posts across your networks'],['Technology','#OpenWeb','1.8k posts across your networks'],['A little inspiration','#SlowLiving','864 posts across your networks']].map(([a,b,c])=>`<button class="trend full" style="text-align:left" data-search="${b.slice(1)}"><small>${a}</small><strong>${b}</strong><small>${c}</small></button>`).join('')}</section><section class="card right-card"><div class="section-heading"><h2>People to know</h2><a href="#Search">See all</a></div>${[['JL','Jules Laurent','jules.bsky.social','green'],['NK','Nina Kim','nina@mastodon.social','purple']].map(([i,n,h,c])=>`<div class="person"><span class="avatar ${c}">${i}</span><span><span class="name small">${n}</span><br><span class="meta" style="font-size:10px">${h}</span></span><button data-follow>Follow</button></div>`).join('')}</section><div class="footer"><span>About</span><span>Privacy</span><span>Terms</span><span>Feedback</span><br>© 2026 Zing · A little more connected.</div></aside>`}
function render(){document.getElementById('root').innerHTML=`<div class="app">${sidebar()}<main class="main"><header class="topbar"><div><div class="eyebrow">YOUR WORLD, CONNECTED</div><div class="greeting">${page==='Home'?'Good to see you, Agim.':page}</div></div><div class="top-actions"><button class="round" data-theme aria-label="Change theme">${icon('Sun')}</button><button class="avatar" data-go="Settings" aria-label="Account settings">AG</button></div></header>${page==='Home'?'<div class="hero-note"><span class="status-ring"></span>A little from everywhere. All in one place.</div>':''}${page==='Home'?`<div class="status-controls">Preview state <select id="state-select">${['normal','loading','empty','disconnected','rate-limit'].map(s=>`<option ${state===s?'selected':''}>${s}</option>`).join('')}</select></div>`:''}${main()}</main>${right()}</div>`;bind()}
function toast(t){document.querySelector('.toast')?.remove();let d=document.createElement('div');d.className='toast';d.role='status';d.textContent=t;document.body.append(d);setTimeout(()=>d.remove(),4000)}
function showModal(html){document.querySelector('.modal-backdrop')?.remove();let d=document.createElement('div');d.className='modal-backdrop';d.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="Zing dialog"><button data-close style="float:right" aria-label="Close">✕</button>${html}</section>`;document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.remove();d.onclick=e=>{if(e.target===d)d.remove()};d.querySelector('input,button')?.focus()}
function go(p){page=p;location.hash=p;render();window.scrollTo(0,0)}
function auth(mode){showModal(`<h2>${mode==='register'?'Find your people.':mode==='forgot'?'A fresh start.':mode==='reset'?'Set a new password.':mode==='verify'?'Check your inbox.':'Welcome back.'}</h2><p class="subtitle">${mode==='verify'?'A verification link is on its way. This is a design preview.':'A little more connected, starting here.'}</p><form id="auth-form">${mode==='register'?'<label class="field">Your name<input required autocomplete="name"></label>':''}${mode!=='verify'?'<label class="field">Email<input type="email" required autocomplete="email" placeholder="you@example.com"></label>':''}${['login','register','reset'].includes(mode)?'<label class="field">Password<input type="password" required minlength="8" autocomplete="'+(mode==='login'?'current-password':'new-password')+'"></label>':''}<button class="primary full">${mode==='register'?'Create your account':mode==='forgot'?'Send reset link':mode==='verify'?'Back to sign in':'Continue'}</button></form><p class="small" style="text-align:center"><button id="switch-auth">${mode==='login'?'New here? Create an account':'Already here? Sign in'}</button></p>${mode==='login'?'<button id="forgot-auth" class="full meta">Forgot your password?</button>':''}<div class="notice">Design preview · don’t enter real credentials.</div>`);document.getElementById('auth-form').onsubmit=e=>{e.preventDefault();if(mode==='register')auth('verify');else if(mode==='forgot')auth('reset');else{document.querySelector('.modal-backdrop').remove();toast('Simulated sign-in complete')}};document.getElementById('switch-auth').onclick=()=>auth(mode==='login'?'register':'login');document.getElementById('forgot-auth')?.addEventListener('click',()=>auth('forgot'))}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});document.querySelectorAll('[data-toast]').forEach(b=>b.onclick=()=>toast(b.dataset.toast));document.querySelectorAll('[data-like]').forEach(b=>b.onclick=()=>{let p=posts.find(p=>p.id===+b.dataset.like);p.liked=!p.liked;p.likes+=p.liked?1:-1;render()});document.querySelectorAll('[data-follow]').forEach(b=>b.onclick=()=>{b.textContent=b.textContent==='Follow'?'Following':'Follow'});document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{let p=posts.find(p=>p.id===+b.dataset.profile)||{name:'Agim',initials:'AG',handle:'agim',color:'',network:'Bluesky'};showModal(`<div class="profile-cover"></div><div class="profile-body"><div class="avatar ${p.color}">${p.initials}</div><h2>${p.name}</h2><p class="meta">@${p.handle} · ${p.network}</p><p class="post-body">Design, community, and a more thoughtful internet.<br>Here for the little things. 🌿</p><p>248 following &nbsp; 1,204 followers</p><button class="primary" id="profile-follow">Follow</button> <button class="secondary" id="profile-message">Message</button></div>`);document.getElementById('profile-follow').onclick=e=>e.target.textContent='Following';document.getElementById('profile-message').onclick=()=>{document.querySelector('.modal-backdrop').remove();go('Messages')}});
document.querySelectorAll('[data-menu]').forEach(b=>b.onclick=()=>{showModal('<h2>Post options</h2><div class="stack"><button class="secondary" data-option>Mute this account</button><button class="secondary" data-option>Block this account</button><button class="secondary" data-option>Report post</button></div>');document.querySelectorAll('[data-option]').forEach(x=>x.onclick=()=>{document.querySelector('.modal-backdrop').remove();toast('Sample action recorded')})});document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>toast('Saved in this design session'));document.querySelectorAll('[data-share]').forEach(b=>b.onclick=()=>toast('Sample post · no public permalink'));document.querySelectorAll('[data-repost]').forEach(b=>b.onclick=()=>toast('Sample repost · original network only'));document.querySelectorAll('[data-reply]').forEach(b=>b.onclick=()=>{go('Compose');document.getElementById('compose-text').value='@'+posts.find(p=>p.id===+b.dataset.reply).handle+' '});document.querySelectorAll('[data-connect]').forEach(b=>b.onclick=()=>{let n=b.dataset.connect;showModal(`<h2>Connect ${n}</h2><p class="subtitle">Bring your world a little closer.</p>${n==='Mastodon'?'<label class="field">Your server<input placeholder="mastodon.social"></label>':''}<div class="notice">${n==='Threads'?'Threads needs a configured developer app and approved permissions before public use.':'The finished app will securely redirect you to '+n+'. Tokens never reach the browser.'}</div><button class="primary full" id="connect-demo">Preview connection</button>`);document.getElementById('connect-demo').onclick=()=>{document.querySelector('.modal-backdrop').remove();toast('Connection preview only · no account connected')}});
document.querySelector('[data-theme]')?.addEventListener('click',()=>{const t=localStorage.getItem('zing-theme')||'system';setTheme(t==='system'?'light':t==='light'?'dark':'system');toast('Theme: '+localStorage.getItem('zing-theme'))});document.getElementById('theme-select')?.addEventListener('change',e=>setTheme(e.target.value));document.getElementById('state-select')?.addEventListener('change',e=>{state=e.target.value;render()});document.querySelector('[data-upload]')?.addEventListener('click',()=>document.getElementById('image-file').click());document.getElementById('image-file')?.addEventListener('change',e=>{document.getElementById('attachment').textContent=e.target.files[0]?.name||''});document.querySelector('[data-emoji]')?.addEventListener('click',()=>{document.getElementById('compose-text').value+=' ✨'});
document.querySelector('[data-publish]')?.addEventListener('click',()=>{const t=document.getElementById('compose-text').value.trim();if(!t)return toast('Write a little something first.');if(document.getElementById('schedule')?.value){saveDraft();return toast('Scheduled in the design preview')}posts.unshift({id:Date.now(),name:'Agim',handle:'agim.bsky.social',network:'Bluesky',time:'now',initials:'AG',color:'',body:t,likes:0,replies:0,reposts:0});go('Home');toast('Sample post added · no network contacted')});document.querySelector('[data-draft]')?.addEventListener('click',saveDraft);document.querySelectorAll('[data-delete-draft]').forEach(b=>b.onclick=()=>{drafts.splice(+b.dataset.deleteDraft,1);persistDrafts();render()});document.querySelectorAll('[data-edit-draft]').forEach(b=>b.onclick=()=>{const d=drafts[+b.dataset.editDraft];go('Compose');document.getElementById('compose-text').value=d.text});document.querySelector('[data-deliveries]')?.addEventListener('click',()=>showModal('<h2>Delivery history</h2><div class="notice">Sample status · partial delivery</div><p>Bluesky <strong style="float:right">Published</strong></p><p>Mastodon <strong style="float:right">Rate limited</strong></p><p>Threads <strong style="float:right">Setup required</strong></p><p class="meta">Only failed destinations can be retried. Successful posts are not duplicated.</p>'));
['search-form','side-search'].forEach(id=>document.getElementById(id)?.addEventListener('submit',e=>{e.preventDefault();search=new FormData(e.target).get('q');go('Search')}));document.querySelectorAll('[data-search]').forEach(b=>b.onclick=()=>{search=b.dataset.search;go('Search')});document.getElementById('message-form')?.addEventListener('submit',e=>{e.preventDefault();messages.push(new FormData(e.target).get('message'));render()});document.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>auth(b.dataset.auth));document.querySelector('[data-delete-account]')?.addEventListener('click',()=>showModal('<h2>Delete your Zing account?</h2><p class="subtitle">The finished app removes your Zing data and connections. Posts already published on other networks remain there.</p><button class="secondary full" data-close>Cancel</button>'))}
function persistDrafts(){localStorage.setItem('zing-design-drafts',JSON.stringify(drafts))}function saveDraft(){const text=document.getElementById('compose-text').value.trim();if(!text)return toast('Add some text to your draft.');drafts.unshift({text,schedule:document.getElementById('schedule')?.value||''});persistDrafts();go('Publishing');toast('Saved in this browser · design sample')}
function setTheme(t){localStorage.setItem('zing-theme',t);if(t==='system')delete document.body.dataset.theme;else document.body.dataset.theme=t}setTheme(localStorage.getItem('zing-theme')||'system');window.addEventListener('hashchange',()=>{const p=decodeURIComponent(location.hash.slice(1));if(['Home','Search','Compose','Notifications','Messages','Publishing','Settings'].includes(p)&&p!==page){page=p;render()}});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('.modal-backdrop')?.remove();if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();go('Search');document.querySelector('input[name=q]')?.focus()}});page=location.hash.slice(1)||'Home';render();
